CREATE FUNCTION ink_product_engine.ink_s4_fixture_id_v1(p_session uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$ SELECT p_session NOT IN ('a3500000-0000-4000-9000-000000009801','a3500000-0000-4000-9000-000000009802','a3500000-0000-4000-9000-000000009701','a3500000-0000-4000-9000-000000009702') $$$pr63_stmt_149$; END IF; END $pr63_if_149$;
