 SELECT EXISTS(SELECT FROM ink_product.rooms r JOIN ink_product.s5_phase2_policies_v1 p USING(binding) WHERE r.session_id=p_session AND r.binding->>'schemaVersion'='candidate-v3')$$$pr63_stmt_153$; END IF; END $pr63_if_153$;
