    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 SELECT EXISTS(SELECT FROM ink_product.rooms r JOIN ink_product.s5_phase3_policies_v1 p USING(binding)WHERE r.session_id=p_session)$$$pr63_stmt_344$; END IF; END $pr63_if_344$;
