CREATE FUNCTION ink_product.claim_review_room_v1(p_room uuid, p_actor uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE r ink_product.rooms; why text; ctl ink_product.review_access_v1;
BEGIN
 SELECT * INTO STRICT r FROM ink_product.rooms WHERE id=p_room;
 IF r.binding->>'schemaVersion' IS DISTINCT FROM 'candidate-v3' THEN RETURN; END IF;
 -- This is a newly inserted, still unclaimed allocation, including a rematch.
 -- Recheck allocation limits rather than the existing-rematch lookup branch.
 why:=ink_product.review_admission_v1('create',p_actor,NULL,'{}',r.binding);
 IF why IS NOT NULL THEN RAISE EXCEPTION '%',why USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT ctl FROM ink_product.review_access_v1 WHERE singleton FOR UPDATE;
 INSERT INTO ink_product.review_room_claims_v1(room_id,window_id,actor_id,accepted_at)
