CREATE FUNCTION ink_product.observe_maintenance_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j record;now_at timestamptz:=clock_timestamp();alert_kind text;n integer:=0;
BEGIN
 FOR j IN SELECT * FROM ink_product.maintenance_jobs_v1 WHERE enabled LOOP
  FOREACH alert_kind IN ARRAY ARRAY['consecutive_errors','overdue']LOOP
   IF(alert_kind='consecutive_errors'AND j.consecutive_errors>=3)OR(alert_kind='overdue'AND now_at>j.next_due_at+interval '5 minutes')THEN
    INSERT INTO ink_product.maintenance_alerts_v1(job,kind,opened_at,body)VALUES(j.job,alert_kind,now_at,jsonb_build_object('job',j.job,'kind',alert_kind,'consecutiveErrors',j.consecutive_errors,'dueAt',j.next_due_at,'observedAt',now_at))ON CONFLICT(job,kind)WHERE resolved_at IS NULL DO NOTHING;
   ELSE UPDATE ink_product.maintenance_alerts_v1 a SET resolved_at=now_at WHERE a.job=j.job AND a.kind=alert_kind AND resolved_at IS NULL;END IF;
  END LOOP;
 END LOOP;
 SELECT count(*)INTO n FROM ink_product.maintenance_alerts_v1 WHERE resolved_at IS NULL;
 RETURN jsonb_build_object('ok',true,'openAlerts',n);
END $$$pr63_stmt_1107$; END IF; END $pr63_if_1107$;
