-- Name: review_admission_v1(text, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: ink_product; Owner: ink_product_owner
--

CREATE FUNCTION ink_product.review_admission_v1(p_operation text, p_actor uuid, p_room uuid, p_payload jsonb, p_binding jsonb) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE ctl ink_product.review_access_v1; at_time timestamptz; actor_hash text;
 target uuid; used_rooms integer; active_rooms integer;
BEGIN
 IF p_binding->>'schemaVersion' IS DISTINCT FROM 'candidate-v3'
    OR p_operation NOT IN('create','join','rematch','start') THEN RETURN NULL; END IF;
 -- Recovery of an existing waiting membership is not a new admission.
 IF p_operation='join' AND EXISTS(SELECT FROM ink_product.rooms r JOIN ink_product.members m ON m.room_id=r.id
   WHERE r.binding=p_binding AND r.phase='waiting' AND r.code=p_payload->>'roomCode'
   AND m.actor_id=p_actor AND m.status='waiting') THEN RETURN NULL; END IF;
 -- Serialize distinct actors and admin OFF/config changes through one row lock.
 SELECT * INTO ctl FROM ink_product.review_access_v1 WHERE singleton FOR UPDATE;
 IF NOT FOUND OR NOT ctl.enabled THEN RETURN 'S5_REVIEW_CLOSED'; END IF;
 -- A real row version change makes stale REPEATABLE READ transactions fail
 -- with 40001 instead of counting room claims from an old snapshot.
 UPDATE ink_product.review_access_v1 SET lock_revision=lock_revision+1
  WHERE singleton RETURNING * INTO ctl;
 at_time:=clock_timestamp();
 IF at_time<ctl.opens_at THEN RETURN 'S5_REVIEW_NOT_OPEN'; END IF;
 IF at_time>=ctl.closes_at THEN RETURN 'S5_REVIEW_EXPIRED'; END IF;
 IF p_operation IN('create','rematch','start') AND at_time>=ctl.starts_until THEN RETURN 'S5_REVIEW_STARTS_CLOSED'; END IF;
 IF NOT EXISTS(SELECT FROM ink_product.entry_policy_v1 WHERE channel='review' AND binding=p_binding)
 THEN RETURN 'S5_REVIEW_BINDING_DENIED'; END IF;
 SELECT encode(sha256(convert_to(string_agg(label||':'||actor_id::text,',' ORDER BY label),'UTF8')),'hex') INTO actor_hash
 FROM ink_product.review_actors_v1;
 IF (SELECT count(*) FROM ink_product.review_actors_v1)<>3 OR actor_hash IS DISTINCT FROM ctl.actor_set_sha256
 THEN RETURN 'S5_REVIEW_ACTOR_SET_INVALID'; END IF;
 IF NOT EXISTS(SELECT FROM ink_product.review_actors_v1 WHERE actor_id=p_actor)
 THEN RETURN 'S5_REVIEW_ACTOR_DENIED'; END IF;
 IF p_operation='join' THEN
  SELECT r.id INTO target FROM ink_product.rooms r WHERE r.binding=p_binding AND r.phase='waiting' AND r.code=p_payload->>'roomCode';
  IF target IS NOT NULL AND NOT EXISTS(SELECT FROM ink_product.review_room_claims_v1 WHERE room_id=target AND window_id=ctl.window_id)
  THEN RETURN 'S5_REVIEW_ROOM_SCOPE'; END IF;
  RETURN NULL;
 ELSIF p_operation='start' THEN
  IF NOT EXISTS(SELECT FROM ink_product.review_room_claims_v1 WHERE room_id=p_room AND window_id=ctl.window_id)
  THEN RETURN 'S5_REVIEW_ROOM_SCOPE'; END IF;
  RETURN NULL;
 ELSIF p_operation='rematch' THEN
  SELECT id INTO target FROM ink_product.rooms WHERE previous_room_id=p_room;
  IF target IS NOT NULL THEN
   IF EXISTS(SELECT FROM ink_product.review_room_claims_v1 WHERE room_id=target AND window_id=ctl.window_id) THEN RETURN NULL; END IF;
   RETURN 'S5_REVIEW_ROOM_SCOPE';
  END IF;
 END IF;
 SELECT count(*) INTO used_rooms FROM ink_product.review_room_claims_v1 WHERE window_id=ctl.window_id;
 IF used_rooms>=ctl.maximum_rooms THEN RETURN 'S5_REVIEW_ROOM_LIMIT'; END IF;
 SELECT count(*) INTO active_rooms FROM ink_product.review_room_claims_v1 q JOIN ink_product.rooms r ON r.id=q.room_id
 WHERE q.window_id=ctl.window_id AND (r.phase='playing' OR(r.phase='waiting' AND EXISTS
  (SELECT FROM ink_product.members m WHERE m.room_id=r.id AND m.status='waiting')));
 IF active_rooms>=ctl.maximum_active_rooms THEN RETURN 'S5_REVIEW_ACTIVE_ROOM_LIMIT'; END IF;
 RETURN NULL;
END $$$pr63_stmt_1109$; END IF; END $pr63_if_1109$;
