DO $pr63_if_1111$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='fresh' THEN EXECUTE $pr63_stmt_1111$--
-- Name: run_maintenance_v1(text, uuid, integer); Type: FUNCTION; Schema: ink_product; Owner: ink_product_owner
--

CREATE FUNCTION ink_product.run_maintenance_v1(p_job text, p_request uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j ink_product.maintenance_jobs_v1;old ink_product.maintenance_runs_v1;now_at timestamptz:=clock_timestamp();result jsonb;status text:='success';state text;remaining boolean:=false;
BEGIN
 IF p_request IS NULL OR p_job IS NULL OR p_job NOT IN('minute_cleanup','daily_receipts')OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 64 THEN RAISE EXCEPTION 'INVALID_MAINTENANCE_REQUEST' USING ERRCODE='22023';END IF;
 SELECT * INTO old FROM ink_product.maintenance_runs_v1 WHERE job=p_job AND request_id=p_request;
 IF FOUND THEN RETURN old.response;END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('s5-maintenance:'||p_job,0))THEN RETURN jsonb_build_object('ok',true,'code','BUSY');END IF;
 SELECT * INTO j FROM ink_product.maintenance_jobs_v1 WHERE job=p_job FOR UPDATE;
 IF NOT j.enabled THEN RETURN jsonb_build_object('ok',false,'code','SCHEDULER_HOLD');END IF;
 IF now_at<j.next_due_at THEN RETURN jsonb_build_object('ok',true,'code','NOT_DUE','nextDueAt',j.next_due_at);END IF;
 -- Advisory lock may have waited at a prior statement boundary; repeat idempotency under the job lock.
 SELECT * INTO old FROM ink_product.maintenance_runs_v1 WHERE job=p_job AND request_id=p_request;
 IF FOUND THEN RETURN old.response;END IF;
 PERFORM ink_product.observe_maintenance_v1();
 BEGIN
  IF p_job='minute_cleanup'THEN
   result:=ink_product.run_due_batch_v1('a3500000-0000-4000-9000-000000000019',p_limit);
   IF coalesce((result->>'errors')::integer,0)>0 THEN RAISE EXCEPTION 'CLEANUP_ROOM_ERRORS';END IF;
   SELECT EXISTS(SELECT FROM ink_product.rooms r WHERE r.phase='playing'AND ink_product.has_due_v2(r.id))INTO remaining;
  ELSE result:=ink_product.purge_receipts_v1(p_limit);
   SELECT EXISTS(SELECT FROM ink_product.rooms r JOIN ink_product.s5_phase5_policies_v1 p USING(binding)JOIN ink_product.group_lifecycle_v1 l ON l.room_id=r.id WHERE r.phase='finished'AND l.closed_at<=now_at-interval '30 days'AND NOT EXISTS(SELECT FROM ink_product.receipt_retention_v1 t WHERE t.room_id=r.id))INTO remaining;
  END IF;
  IF remaining THEN status:='partial';END IF;
 EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS state=RETURNED_SQLSTATE;status:='failed';result:=jsonb_build_object('ok',false,'code','MAINTENANCE_FAILED','sqlstate',state);END;
 IF status='failed'THEN UPDATE ink_product.maintenance_jobs_v1 SET consecutive_errors=consecutive_errors+1,last_error=state WHERE job=p_job;
 ELSE UPDATE ink_product.maintenance_jobs_v1 SET consecutive_errors=0,last_error=NULL,last_completed_at=clock_timestamp(),next_due_at=CASE WHEN remaining THEN j.next_due_at WHEN p_job='minute_cleanup'THEN date_trunc('minute',clock_timestamp())+interval '1 minute'ELSE(date_trunc('day',clock_timestamp()AT TIME ZONE 'UTC')+interval '1 day')AT TIME ZONE 'UTC'END WHERE job=p_job;END IF;
 result:=result||jsonb_build_object('job',p_job,'requestId',p_request,'scheduledAt',j.next_due_at,'status',status);
 INSERT INTO ink_product.maintenance_runs_v1 VALUES(p_job,p_request,j.next_due_at,now_at,clock_timestamp(),status,result);
 PERFORM ink_product.observe_maintenance_v1();RETURN result;
END $$$pr63_stmt_1111$; END IF; END $pr63_if_1111$;
