DO $pr63_if_1429$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1429$-- Only genuine, validated daily children are normalized. Parent, functions,
-- policies, ACLs and every application object remain in the baseline hash.
CREATE FUNCTION pg_temp.pr63_catalogue() RETURNS jsonb LANGUAGE sql AS $catalogue$
SELECT jsonb_build_object(
 'tables',(SELECT coalesce(jsonb_agg(x ORDER BY schema,name),'[]') FROM (SELECT n.nspname AS schema,c.relname AS name,c.relkind,c.relpersistence,pg_get_userbyid(c.relowner) AS owner,c.relrowsecurity AS rls,c.relforcerowsecurity AS force_rls,c.relacl::text AS acl,c.reloptions,pg_get_partkeydef(c.oid) AS partition_key FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema' AND c.relkind IN ('r','p','S','v','m','f'))x),
 'columns',(SELECT coalesce(jsonb_agg(x ORDER BY schema,table_name,num),'[]') FROM (SELECT n.nspname AS schema,c.relname AS table_name,a.attnum AS num,a.attname AS name,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid) AS default_expr,a.attacl::text AS acl FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema' AND a.attnum>0 AND NOT a.attisdropped AND c.relkind IN ('r','p','v','m','f'))x),
 'constraints',(SELECT coalesce(jsonb_agg(x ORDER BY schema,table_name,name),'[]') FROM (SELECT n.nspname AS schema,c.relname AS table_name,o.conname AS name,o.contype,o.convalidated,pg_get_constraintdef(o.oid) AS definition FROM pg_constraint o JOIN pg_class c ON c.oid=o.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema')x),
 'indexes',(SELECT coalesce(jsonb_agg(x ORDER BY schemaname,tablename,indexname),'[]') FROM (SELECT schemaname,tablename,indexname,indexdef FROM pg_indexes WHERE schemaname NOT LIKE 'pg_%' AND schemaname<>'information_schema')x),
 'policies',(SELECT coalesce(jsonb_agg(x ORDER BY schemaname,tablename,policyname),'[]') FROM (SELECT * FROM pg_policies WHERE schemaname NOT LIKE 'pg_%')x),
 'functions',(SELECT coalesce(jsonb_agg(x ORDER BY schema,name,args),'[]') FROM (SELECT n.nspname AS schema,p.proname AS name,pg_get_function_identity_arguments(p.oid) AS args,pg_get_function_result(p.oid) AS result,pg_get_userbyid(p.proowner) AS owner,p.proacl::text AS acl,p.prosecdef,p.provolatile,p.proisstrict,p.proleakproof,p.proconfig,md5(pg_get_functiondef(p.oid)) AS definition_md5 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema' AND p.prokind IN ('f','p'))x),
 'triggers',(SELECT coalesce(jsonb_agg(x ORDER BY schema,table_name,name),'[]') FROM (SELECT n.nspname AS schema,c.relname AS table_name,t.tgname AS name,t.tgenabled,pg_get_triggerdef(t.oid) AS definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema' AND NOT t.tgisinternal)x),
 'schemas',(SELECT jsonb_agg(x ORDER BY name) FROM (SELECT nspname AS name,pg_get_userbyid(nspowner) AS owner,nspacl::text AS acl FROM pg_namespace n WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname <> 'information_schema')x),
 'default_acl',(SELECT coalesce(jsonb_agg(x ORDER BY role,schema,type),'[]') FROM (SELECT pg_get_userbyid(d.defaclrole) AS role,coalesce(n.nspname,'') AS schema,d.defaclobjtype AS type,d.defaclacl::text AS acl FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace)x),
 'extensions',(SELECT jsonb_agg(x ORDER BY extname) FROM (SELECT e.extname,e.extversion,n.nspname AS schema FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace)x),
 'publications',(SELECT coalesce(jsonb_agg(x ORDER BY pubname),'[]') FROM (SELECT pubname,pg_get_userbyid(pubowner) AS owner,puballtables,pubinsert,pubupdate,pubdelete,pubtruncate,pubviaroot FROM pg_publication)x),
 'publication_tables',(SELECT coalesce(jsonb_agg(x ORDER BY pubname,schemaname,tablename),'[]') FROM (SELECT * FROM pg_publication_tables)x)
 ) AS catalogue;
$catalogue$$pr63_stmt_1429$; END IF; END $pr63_if_1429$;
DO $pr63_if_1430$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1430$CREATE FUNCTION pg_temp.pr63_part_catalogue(cat jsonb, part text) RETURNS jsonb LANGUAGE sql AS $part$
 SELECT replace(jsonb_object_agg(key,items)::text,part,'messages_DATE')::jsonb
 FROM (SELECT key,coalesce((SELECT jsonb_agg(v ORDER BY ord) FROM jsonb_array_elements(value) WITH ORDINALITY a(v,ord)
 WHERE coalesce(v->>'schema',v->>'schemaname')='realtime'
 AND coalesce(v->>'table_name',v->>'tablename',CASE WHEN key='tables' THEN v->>'name' END)=part),'[]'::jsonb) AS items
 FROM jsonb_each(cat) WHERE key IN('tables','columns','constraints','indexes','policies','triggers','publication_tables'))s;
$part$$pr63_stmt_1430$; END IF; END $pr63_if_1430$;
DO $pr63_if_1431$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1431$CREATE FUNCTION pg_temp.pr63_stable_catalogue(cat jsonb, parts text[]) RETURNS jsonb LANGUAGE sql AS $stable$
 SELECT jsonb_object_agg(key,items) FROM (SELECT key,coalesce((SELECT jsonb_agg(v ORDER BY ord)
 FROM jsonb_array_elements(value) WITH ORDINALITY a(v,ord)
 WHERE NOT(coalesce(v->>'schema',v->>'schemaname','')='realtime'
 AND coalesce(v->>'table_name',v->>'tablename',CASE WHEN key='tables' THEN v->>'name' END,'')=ANY(parts))),'[]'::jsonb) AS items FROM jsonb_each(cat))s;
$stable$$pr63_stmt_1431$; END IF; END $pr63_if_1431$;
DO $pr63_if_1432$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1432$DO $target$
DECLARE cat jsonb; p record; day date; live text[]; original text;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'PR63_POSTGRES_EXECUTOR_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('pr63-s5-existing-objects-bridge',0));
 cat:=pg_temp.pr63_catalogue();
 SELECT coalesce(array_agg(c.relname::text),'{}') INTO live FROM pg_inherits i JOIN pg_class c ON c.oid=i.inhrelid WHERE i.inhparent='realtime.messages'::regclass;
 FOR p IN SELECT c.oid,c.relname,n.nspname,c.relkind,c.relispartition,pg_get_expr(c.relpartbound,c.oid) AS bound
 FROM pg_inherits i JOIN pg_class c ON c.oid=i.inhrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE i.inhparent='realtime.messages'::regclass LOOP
  IF p.nspname<>'realtime' OR p.relkind<>'r' OR NOT p.relispartition OR p.relname !~ '^messages_[0-9]{4}_[0-9]{2}_[0-9]{2}$' THEN RAISE EXCEPTION 'BRIDGE_PARTITION_IDENTITY_DRIFT'; END IF;
  day:=to_date(substr(p.relname,10),'YYYY_MM_DD');
