DO $pr63_if_1478$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1478$CREATE OR REPLACE FUNCTION ink_product.fixed_supply_draw_v1(p_session uuid, p_participant uuid, p_round bigint, p_draw bytea)
 RETURNS text
 LANGUAGE sql
 STABLE STRICT
