DO $pr63_if_1479$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1479$CREATE OR REPLACE FUNCTION ink_product.forfeit_match_v1(p_room uuid, p_actor uuid)
