DO $pr63_if_1482$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1482$CREATE OR REPLACE FUNCTION ink_product.has_due_v2(p_room uuid)
