  IF ink_product_engine.ink_s5_phase2_enabled_v1(r.session_id)THEN b:=b||jsonb_build_object('phase2Policy',true,'search',ink_product_engine.ink_s5_phase2_search_state_v1(e,now_at));END IF;
  RETURN b;
