DO $pr63_if_1500$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1500$CREATE OR REPLACE FUNCTION ink_product_engine.ink_s2_next_event_v1(p_session uuid, p_participant uuid)
 RETURNS bigint
 LANGUAGE sql
 SET search_path TO ''
