DO $pr63_if_1506$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1506$CREATE OR REPLACE FUNCTION ink_product_engine.ink_s3_due_round_v1(p_started timestamp with time zone, p_at timestamp with time zone)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
  SELECT CASE WHEN p_at<p_started THEN -1
