DO $pr63_if_1529$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1529$CREATE OR REPLACE FUNCTION ink_product_engine.ink_s4_trap_choices_v1(p_session uuid, p_member ink_product_engine.ink_members_v1, p_target uuid, p_grant uuid, p_at timestamp with time zone)
