DO $pr63_if_1542$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1542$CREATE OR REPLACE FUNCTION ink_product_engine.ink_s5_close_thunder_v1(p_session uuid, p_effect ink_product_engine.ink_s4_effects_v1, p_at timestamp with time zone, p_receipt uuid)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
