DO $pr63_if_1581$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1581$CREATE OR REPLACE FUNCTION ink_product_engine.ink_s5_phase2_expire_rewards_v1(p_session uuid, p_at timestamp with time zone, p_receipt uuid, p_terminal boolean)
