DO $pr63_if_1582$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1582$CREATE OR REPLACE FUNCTION ink_product_engine.ink_s5_phase2_offer_trigger_v1()
