DO $pr63_if_1583$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1583$CREATE OR REPLACE FUNCTION ink_product_engine.ink_s5_phase2_reward_head_v1(p_member ink_product_engine.ink_members_v1, p_at timestamp with time zone)
