DO $pr63_if_1593$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1593$CREATE OR REPLACE FUNCTION ink_product_engine.ink_s5_resolve_attack_v1(p_session uuid, p_child uuid, p_at timestamp with time zone, p_reflect boolean, p_receipt uuid)
