DO $pr63_if_1602$ BEGIN IF (SELECT mode FROM pg_temp._pr63_install_mode)='existing' THEN EXECUTE $pr63_stmt_1602$CREATE OR REPLACE FUNCTION ink_product_engine.ink_s5_weakening_v2(p_member ink_product_engine.ink_members_v1, p_tier text, p_at timestamp with time zone, p_receipt uuid)
